class Definition(Document):
    """Immutable source dataset parameters; independent of presentation fixtures."""

    symbol: str = Field(min_length=1, max_length=100, pattern=r"^[A-Za-z0-9_@.$-]+$")
    postfix: str = Field(default="", max_length=28, pattern=r"^[A-Za-z0-9_.-]*$")
    timeframe: Literal["M1", "D1"] = "D1"
    adjusted: bool = True
    instrument: str = Field(default="", max_length=128)
    broker: str = "-1"


class Download(Document):
    """Explicit inclusive acquisition range."""

    dataset_id: str
    date_from: date
    date_to: date
    only_missing: bool = True

    @model_validator(mode="after")
    def dates(self) -> Download:
        """Reject backwards and unsupported dates before starting a job."""
        if self.date_from > self.date_to or self.date_from.year < 1900:
            raise ValueError("Invalid historical date range")
        return self


class Credentials(Document):
    """Write-only credentials; never exposed through catalog or job status."""

    username: SecretStr
    password: SecretStr


class Search(Document):
    """Source catalog lookup controls with bounded result count."""

    query: str = Field(default="", max_length=10000)
    exchange: str = ""
    exact: bool = False
    search_ticker: bool = True
    search_name: bool = True
    continuous_only: bool = False
    limit: int = Field(default=1000, ge=1, le=5000)


class Runtime:
    """Own independent acquisition lifecycle and frozen public catalog snapshot."""

    def __init__(
        self, market: MarketAccess, jobs: JobAccess, network: SourceNetwork
    ) -> None:
        self.market, self.jobs, self.network = market, jobs, network
        self.progress: dict[str, dict[str, Any]] = {}
        self.catalog: list[dict[str, Any]] = json.loads(
            zlib.decompress(base64.b85decode(CATALOG_SNAPSHOT))
        )
        self.credentials_configured = network.authentication_configured

    def lookup(self, request: Search) -> list[dict[str, Any]]:
        """Search actual snapshot names and tickers; expose no entitlement guesses."""
        if not request.search_ticker and not request.search_name:
            raise ValueError("Enable ticker or name search")
        terms = [
            term.strip().upper()
            for term in re.split(r"[,;\r\n]+", request.query)
            if term.strip()
        ]
        rows = []
        for row in self.catalog:
            ticker = str(row["ticker"])
            if (
                request.exchange
                and str(row["exchange"]).upper() != request.exchange.upper()
            ):
                continue
            if terms and not any(
                (
                    request.search_ticker
                    and (
                        ticker.upper() in (term, term + ".D")
                        if request.exact
                        else term in ticker.upper()
                    )
                )
                or (request.search_name and term in str(row["name"]).upper())
                for term in terms
            ):
                continue
            rows.append(row)
            if len(rows) >= request.limit:
                break
        return rows

    async def probe(self, url: str) -> int:
        """Use original finite status retry count and exponential backoff."""
        for attempt in range(5):
            response = await self.network.head(url)
            if response.status not in (429, 500, 502, 503, 504) or attempt == 4:
                return response.status
            await asyncio.sleep(0 if attempt == 0 else 0.5 * 2**attempt)
        raise ValueError("Source retry limit exceeded")

    async def acquire(  # noqa: C901, PLR0912 -- source routing.
        self, request: Download, progress: dict[str, Any]
    ) -> None:
        """Resolve original CDN routes, decode real archives and publish by year."""
        record = self.market.source_definition(request.dataset_id)
        definition = Definition.model_validate(record["options"]["parameters"])
        symbol = normalize_symbol_name(record["underlying"])
        folder = "minutes" if definition.timeframe == "M1" else "eod"
        packages = []
        if request.date_from.year < 2019:
            packages.append("data00.zip")
        if request.date_to.year >= 2019:
            packages.append("data01.zip")
        routes = [f"{folder}/{symbol}/{package}" for package in packages]
        adjusted = True and definition.adjusted and definition.timeframe == "D1"
        if adjusted:
            routes = [f"eod/adjusted_{get_adjusted_ident(symbol)}/data.zip"]
        progress["total_chunks"] = len(routes)
        start = pd.Timestamp(request.date_from, tz="UTC")
        end = pd.Timestamp(request.date_to + timedelta(days=1), tz="UTC")
        for route in routes:
            chosen = None
            for base in BASES:
                status = await self.probe(base + route)
                if status in (401, 403):
                    raise ValueError("CDN authentication or subscription required")
                if status == 200:
                    chosen = base + route
                    break
            if chosen is None:
                raise ValueError("Requested CDN archive is unavailable")
            async with self.network.archive(chosen) as archive:
                names = archive.members()
                if True:
                    names = tuple(sorted(names))
                for name in names:
                    if not name.endswith(".dat") or (
                        adjusted and not name.startswith(symbol + "/")
                    ):
                        continue
                    year_match = re.search(r"(\d{4})", name.rsplit("/", 1)[-1])
                    if (
                        year_match
                        and not request.date_from.year
                        <= int(year_match[1])
                        <= request.date_to.year
                    ):
                        continue
                    frame = await self.jobs.offload(
                        SQBinaryDatDecoder.decode, archive.read(name)
                    )
                    frame = frame[
                        (frame["DateTime"] >= start) & (frame["DateTime"] < end)
                    ]
                    if len(frame):
                        self.publish(
                            request.dataset_id,
                            frame,
                            definition.timeframe,
                            request.only_missing,
                            progress,
                        )
                    await asyncio.sleep(0)
            progress["completed_chunks"] += 1
        if not progress["rows"]:
            raise ValueError("No historical rows were returned for this range")

    def publish(
        self,
        dataset_id: str,
        frame: pd.DataFrame,
        timeframe: str,
        only_missing: bool,
        progress: dict[str, Any],
    ) -> None:
        """Merge canonical years with source incoming-last duplicate precedence."""
        for year, incoming in frame.groupby(
            pd.to_datetime(frame["DateTime"], utc=True).dt.year
        ):
            part = incoming
            period = str(year)
            previous = next(
                (
                    row
                    for row in self.market.source_partitions(dataset_id)
                    if row["period"] == period
                ),
                None,
            )
            if previous:
                old = self.market.read_source_partition(dataset_id, period).to_pandas()
                part = pd.concat(
                    [part, old] if only_missing else [old, part], ignore_index=True
                )
            table = dataframe_to_canonical_table(part, timeframe.lower())
            self.market.publish_source(
                dataset_id,
                period,
                table,
                expected_revision=previous["revision"] if previous else 0,
            )
            progress["published_partitions"] += 1
            logger.info(
                "SQ source partition published: dataset=%s year=%s", dataset_id, period
            )
        progress["rows"] += len(frame)

    async def invoke(  # noqa: C901 -- explicit operations.
        self, operation: str, payload: JsonValue
    ) -> JsonValue:
        """Expose actual metadata, definitions, credentials and host-owned jobs."""
        values = payload if isinstance(payload, dict) else {}
        logger.info("SQ source operation: %s", operation)
        if operation == "credentials.configure":
            credentials = Credentials.model_validate(values)
            self.network.configure_basic_auth(
                ORIGIN,
                credentials.username.get_secret_value(),
                credentials.password.get_secret_value(),
            )
            self.credentials_configured = True
            return {"configured": True}
        if operation == "catalog":
            ready = self.market.source_available()
            return cast(
                "JsonValue",
                {
                    "available": ready,
                    "reason": ""
                    if ready
                    else "Script-backed catalog migration is required",
                    "datasets": self.market.source_definitions() if ready else [],
                    "catalog_rows": len(self.catalog),
                    "exchanges": sorted(
                        {
                            str(row["exchange"])
                            for row in self.catalog
                            if row["exchange"]
                        }
                    ),
                    "credentials_configured": self.credentials_configured,
                    "schema": Definition.model_json_schema(),
                },
            )
        if operation == "lookup":
            return cast(
                "JsonValue", {"symbols": self.lookup(Search.model_validate(values))}
            )
        if operation == "add":
            definition = Definition.model_validate(values)
            metadata = next(
                (
                    row
                    for row in self.catalog
                    if row["ticker"] == definition.symbol.upper()
                ),
                None,
            )
            if metadata is None:
                raise ValueError("Symbol is not in the source catalog")
            expected = "D1" if metadata["timeframe"] == "D" else "M1"
            if definition.timeframe != expected:
                raise ValueError("Select the catalog entry for the requested timeframe")
            dataset_id = self.market.register_source(
                source="Equity",
                symbol=definition.symbol.upper() + definition.postfix,
                underlying=definition.symbol.upper(),
                instrument=definition.instrument
                or normalize_symbol_name(definition.symbol),
                timeframe=definition.timeframe,
                broker=definition.broker,
                options={
                    "parameters": definition.model_dump(mode="json"),
                    "metadata": metadata,
                },
            )
            return {"id": dataset_id}
        if operation == "download.start":
            request = Download.model_validate(values)
            self.market.source_definition(request.dataset_id)
            progress: dict[str, Any] = {
                "rows": 0,
                "published_partitions": 0,
                "completed_chunks": 0,
                "total_chunks": 0,
            }

            async def run() -> None:
                await self.acquire(request, progress)

            job = self.jobs.submit(Budget(1, 512 * 1024 * 1024, 3600), run)
            self.progress[job.id] = progress
            return {"job_id": job.id, "state": job.state}
        if operation in ("download.status", "download.cancel"):
            job_id = str(values.get("job_id", ""))
            if operation == "download.cancel":
                self.jobs.cancel(job_id)
            job = self.jobs.status(job_id)
            return cast(
                "JsonValue",
                {"job_id": job.id, "state": job.state, **self.progress[job.id]},
            )
        raise ValueError("Unknown SQ source operation")

    async def close(self) -> None:
        """Await jobs and clear the owner's credentials and transport."""
        await self.jobs.close()
        await self.network.close()
        logger.info("SQ source closed")


async def prepare(context: HostCapabilities) -> PreparedContribution:
    """Activate one independent source without ambient paths or mutable peers."""
    if context.market_data is None or context.jobs is None or context.network is None:
        raise ValueError("SQ source requires market data, jobs and network")
    runtime = Runtime(
        context.market_data, context.jobs, context.network.source_session((ORIGIN,))
    )
    return PreparedContribution(
        (
            "catalog",
            "lookup",
            "credentials.configure",
            "add",
            "download.start",
            "download.status",
            "download.cancel",
        ),
        runtime.invoke,
        runtime.close,
    )
